SQL_DOC.P_SQL:
SELECT B.TEXT4 AS xpMroOrd_Site , A.PO_NO AS xpMroOrd_PoNbr , A.PO_SEQ AS xpMroOrd_PoLine , A.STATUS AS xpMroOrd_Status , A.ADD_DATE AS xpMroOrd_AddDate , A.ADD_TIME AS xpMroOrd_AddTime , A.CHANGE_DATE AS xpMroOrd_ModDate , A.CHANGE_TIME AS xpMroOrd_ModTime , A.BUYER_ITEM_NO AS xpMroOrd_Part , A.DESCRIPTION AS xpMroOrd_Desc , A.SPECIFICATION AS xpMroOrd_Spec , A.UNIT_MEASURE AS xpMroOrd_Um , A.ITEM_QTY AS xpMroOrd_qty_ord , A.UNIT_PRICE AS xpMroOrd_Price , A.ITEM_AMT AS xpMroOrd_Amt , A.RD_DATE AS xpMroOrd_DueDate , A.PO_REMARK AS xpMroOrd_ReMark , CASE WHEN A.BUYER = 'KRSEOJ0025' THEN CASE WHEN C.ACCOUNT_TYPE = '55620' THEN '583400' WHEN C.ACCOUNT_TYPE = '60280' THEN '626200' ELSE '583200' END ELSE CASE WHEN C.ACCOUNT_TYPE = '55620' THEN '583400' ELSE '583200' END END AS xpMroOrd_Account , CASE WHEN A.BUYER = 'KRSEOJ0025' THEN C.BUDGET_DEPT ELSE B.TEXT4 END AS xpMroOrd_CostCentre , F_SPLIT(D.CATEG_PATH,' > ',2) AS xpMroOrd_Cat1 , F_SPLIT(D.CATEG_PATH,' > ',3) AS xpMroOrd_Cat2 , F_SPLIT(D.CATEG_PATH,' > ',4) AS xpMroOrd_Cat3 , F_SPLIT(D.CATEG_PATH,' > ',5) AS xpMroOrd_Cat4 FROM ICOMPODT A INNER JOIN ICOMPRDT C ON (1 = 1 AND C.BUYER = A.BUYER AND C.PR_NO = A.PR_NO AND C.PR_SEQ = A.PR_SEQ ) INNER JOIN ICOMCOD2 B ON (1 = 1 AND B.TYPE = 'C012' AND B.CODE = C.DELY_TO_LOCATION AND B.COMPANY_CODE = C.BUYER ) INNER JOIN ICOMBYIT E ON (1 = 1 AND E.BUYER = A.BYIT_COMORG_CODE AND E.BUYER_ITEM_NO = A.BUYER_ITEM_NO ) LEFT OUTER JOIN ICOMBYCA D ON (1 = 1 AND D.COM_CODE = E.BUYER AND D.STD_CATEG_ID = E.CATEGORY_NO ) WHERE A.BUYER = '$G_RS.TARGET$' AND A.PO_NO = '$G_RS.KEY_1$'
BEGIN UPDATE ICOMTRXL SET KEY_8 = 'UPDATE' , KEY_9 = 'Y' , KEY_10 = TO_CHAR(SYSDATE,'YYYY/MM/DD HH24:MI:SS') WHERE DOC_NAME = 'PO_DOWN' AND TARGET = '$G_RS.TARGET$' AND KEY_1 = '$G_RS.KEY_1$' AND KEY_9 = ' ';
UPDATE ICOMPOHD SET SEND_DATE = TO_CHAR(SYSDATE,'YYYYMMDD') , SEND_TIME = TO_CHAR(SYSDATE,'HH24MISS') WHERE BUYER = '$G_RS.TARGET$' AND PO_NO = '$G_RS.KEY_1$';
END;
UPDATE ICOMTRXL SET KEY_8 = 'UPDATE' , KEY_9 = 'E' , KEY_10 = TO_CHAR(SYSDATE,'YYYY/MM/DD HH24:MI:SS') WHERE DOC_NAME = 'PO_DOWN' AND TARGET = '$G_RS.TARGET$' AND KEY_1 = '$G_RS.KEY_1$' AND KEY_9 = ' '
